"""Polygon mattes traced from local anime frames, with OpenCV edge feathering.

Run extract_assets first (or let this script seek the required frames itself).
Every output records its source episode, timestamp and transformation in manifest.
No source video is copied into the game or modified.
"""
from pathlib import Path
import sys,json
import numpy as np
import cv2
from PIL import Image,ImageDraw,ImageEnhance,ImageOps
from extract_assets import frame, ROOT

OUT=ROOT/'assets';OUT.mkdir(exist_ok=True)
manifest=[]

def load(ep,t,season=2):return Image.open(frame(ep,t,season,1920)).convert('RGB')

def cut(name,ep,t,poly,season=2,brightness=1.25,height=512):
    src=load(ep,t,season)
    mask=Image.new('L',src.size);ImageDraw.Draw(mask).polygon(poly,fill=255)
    # Feather less than one source pixel: anti-aliased contour without a halo.
    mat=cv2.GaussianBlur(np.asarray(mask),(3,3),.55)
    rgba=ImageEnhance.Brightness(src).enhance(brightness).convert('RGBA')
    rgba.putalpha(Image.fromarray(mat))
    rgba=rgba.crop(mask.getbbox())
    rgba.thumbnail((768,height),Image.Resampling.LANCZOS)
    rgba.save(OUT/f'{name}.png')
    manifest.append(dict(file=f'{name}.png',season=season,episode=ep,seconds=t,method='manually traced polygon matte; OpenCV feather; brightness '+str(brightness),source_size=list(src.size)))
    return rgba

