# Inspect every extracted silhouette in one contact sheet.
names=['d','scorpion_body','chip','enemy_0','enemy_1','enemy_2','enemy_3','boss','drone','brawler','stalker','charger','guard','berserker','netrunner']
sheet=Image.new('RGB',(1200,900),'#101c2b');draw=ImageDraw.Draw(sheet)
for i,name in enumerate(names):
    im=Image.open(OUT/f'{name}.png');im.thumbnail((220,250));x=(i%5)*240;y=(i//5)*300
    sheet.paste(im,(x+(240-im.width)//2,y+15),im);draw.text((x+20,y+275),name,fill='white')
(ROOT/'screenshots').mkdir(exist_ok=True);sheet.save(ROOT/'screenshots/asset_sheet.png')
print(f'Built {len(manifest)} assets from both local seasons.')
